  'S-03':{title:'Increase my SIP',question:'What changes if I add to this monthly contribution?',kind:'dedicated',formula:'sip',scope:'Compares two end-month contribution paths under the annual rate and period you enter.',fields:[['currentSip','Current monthly SIP','12500'],['extraSip','Additional monthly SIP','2500'],['rate','Annual rate (%)','10'],['years','Years','12']]},
  'S-06':{title:'Debt cost',question:'What does this fixed monthly debt cost over its remaining period?',kind:'dedicated',formula:'debt',scope:'Models a selected home or personal loan. It does not tell you whether to repay or refinance.',fields:[['outstanding','Outstanding balance','486200'],['loanRate','Annual interest rate (%)','9.4'],['months','Remaining whole months','54']]},
  'S-07':{title:'Idle cash over time',question:'What follows if one amount compounds at two rates?',kind:'dedicated',formula:'idle',scope:'Shows two user-authored paths in their original order. It does not name a winner.',fields:[['cashAmount','Cash amount','200000'],['savingsRate','First annual rate (%)','4'],['alternateRate','Second annual rate (%)','8'],['idleYears','Years','10']]},
