  'S-02':{title:'Loan prepayment effects',question:'How does one prepayment change this recorded loan?',kind:'focused',origin:'Home loan',formula:'loan',scope:'Shows same-EMI and same-tenure consequences plus the stored rate as a hurdle. No investment return is projected.',fields:[['prepay','Prepayment amount','100000']]},
  'EX-ESOP':{title:'ESOP exercise cost',question:'What cash would exercising vested options require today?',kind:'focused',origin:'Workplace grant',formula:'esop',scope:'Uses the recorded option grant and India server date. FMV is recorded, not claimed current.',fields:[]},
  'EX-80C':{title:'80C recorded room',question:'What do these fixture contributions total against the fixture cap?',kind:'focused',origin:'Budget',formula:'tax',scope:'Internal fixture only. This is not a current tax calculation or contribution recommendation.',fields:[['regime','Tax regime (old/new)','old']]},
  'EX-TERM':{title:'Household-support scenarios',question:'What do the components you select add up to?',kind:'focused',origin:'Term cover',formula:'term',scope:'Shows selected components and a signed cover difference. It does not decide required or adequate cover.',fields:[['annualSupport','Annual household support','480000'],['supportYears','Support years','12'],['growth','Annual change (%)','0'],['cover','Entered cover','5000000']]}
