const state={task:'discover',account:'Aarav',screen:'tools',tool:null,draft:{},included:new Set(),touched:new Set(),result:null,sourceMode:'ready',offline:false,permission:true,busy:false,progressCount:0,progressCap:false,history:[],origin:null,fixtureId:null};
const $=id=>document.getElementById(id);let returnFocus=null;
const money=n=>`₹${Math.round(n).toLocaleString('en-IN')}`;
const precise=n=>`₹${Number(n).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const finite=(...v)=>v.every(Number.isFinite);const LIMIT=1e15;
function strictNumber(raw){const s=String(raw).trim();if(!s||/[eE]/.test(s))return null;const plain=/^[+-]?\d+(?:\.\d+)?$/;const indian=/^[+-]?\d{1,2}(?:,\d{2})*,\d{3}(?:\.\d+)?$/;const western=/^[+-]?\d{1,3}(?:,\d{3})+(?:\.\d+)?$/;if(!plain.test(s)&&!indian.test(s)&&!western.test(s))return null;const n=Number(s.replaceAll(',',''));return Number.isFinite(n)?n:null}
function announce(text,urgent=false){const n=$(urgent?'urgent-announcement':'polite-announcement');n.textContent='';requestAnimationFrame(()=>n.textContent=text)}
function log(text,urgent=false){const message=state.fixtureId&&!text.startsWith(state.fixtureId)?`${state.fixtureId}: ${text}`:text;$('route-log').textContent=message;announce(message,urgent)}
function setBanner(text='',error=false){const n=$('banner');n.hidden=!text;n.className=`banner${error?' error':''}`;n.textContent=text}
function currentCandidates(){return CANDIDATES[state.account][state.tool]||[]}
function resetTool(){state.draft={};state.included=new Set();state.touched=new Set();state.result=null;state.busy=false;const t=TOOLS[state.tool];for(const [key,,value] of t?.fields||[])state.draft[key]=value}
function enterTool(id,origin=null){state.history.push({screen:state.screen,tool:state.tool,origin:state.origin});state.screen='tool';state.tool=id;state.origin=origin;resetTool();render();focusMain()}
function goBack(){const prev=state.history.pop();if(prev)Object.assign(state,prev);else{state.screen='tools';state.tool=null;state.origin=null}resetTransientResult();render();focusMain()}
function resetTransientResult(){state.result=null;state.busy=false}
function focusMain(){requestAnimationFrame(()=>$('app-content').focus())}
function render(){
  $('account-label').textContent=`${state.account}'s hypothetical account`;$('back').hidden=state.screen==='tools'||!state.permission;$('close').hidden=state.screen==='tools'||!state.permission;setBanner();
  if(!state.permission){$('app-content').innerHTML=`<section class="empty-state"><h1>Sign in to continue</h1><p>All candidates, drafts, results, consent and dialogs were cleared immediately.</p><button class="primary" data-route="Sign in again">Sign in again</button></section>`;bind();return}
  if(state.sourceMode==='loading'){ $('app-content').innerHTML=`<section role="status" aria-busy="true"><h1>Loading ${state.tool?TOOLS[state.tool].title:'Scenarios'}</h1><p class="freshness">Prior-account information was cleared before this request.</p>${'<div class="skeleton"></div>'.repeat(4)}</section>`;bind();return}
  if(state.offline)setBanner('Offline. Manual local scenarios may run. Remote explorers need an explicit retry after reconnect.');
  $('app-content').innerHTML=state.screen==='tools'?renderTools():renderTool();bind();
}
function renderTools(){const cards=Object.entries(TOOLS).filter(([,t])=>t.kind==='dedicated').map(([id,t])=>`<button class="tool-card" data-tool="${id}"><strong>${t.title}</strong><span class="meta">${t.question}</span></button>`).join('');return `<section><h1>Scenarios</h1><p class="lede">Change assumptions. Read the consequence. The choice remains yours.</p><p class="freshness">Five broadly usable scenarios. Focused explorers stay with relevant records.</p></section><section class="section"><h2 class="section-heading">Choose a question</h2><div class="tool-list">${cards}</div></section><section class="section"><h2 class="section-heading">Focused explorer fixtures</h2><div class="link-list"><button data-explorer="S-02">From a loan record</button><button data-explorer="EX-ESOP">From an option grant</button><button data-explorer="EX-80C">From Budget</button><button data-explorer="EX-TERM">From term cover</button></div></section><section class="section"><button data-route="Deferred tools">Why tax/HRA and rent-versus-buy are unavailable</button></section>`}
function renderTool(){const t=TOOLS[state.tool],c=currentCandidates();if(state.sourceMode==='failure')return `<section><h1>${t.title}</h1><div class="error-card" role="alert"><h2>Recorded source unavailable</h2><p>This is not an empty account and no value became zero. Manual entry remains available where safe.</p><button class="primary" data-action="retry">Try this source again</button></div></section>`;
  if(state.sourceMode==='empty'&&t.kind==='focused')return `<section class="empty-state"><h1>${t.title}</h1><p>There is no eligible recorded item to offer. This does not confirm real-world absence.</p><button data-action="back">Return to ${t.origin||'Tools'}</button></section>`;
  const sourceHtml=c.length?`<section class="section"><h2 class="section-heading">Recorded candidates</h2><p class="freshness">Freshness unavailable. Loaded this fixture session.</p><div class="source-list">${c.map(([key,label,value,source])=>`<button class="source-card" data-candidate="${key}" data-included="${state.included.has(key)}"><strong>${label}</strong><span class="meta">${value}. ${source}. ${state.included.has(key)?'Included by you.':'Offered, not included.'}</span></button>`).join('')}</div>${state.sourceMode==='partial'?'<p class="warning panel">One independent source is unavailable. Available candidates remain usable.</p>':''}${state.sourceMode==='stale'?'<p class="warning panel">Authoritative fixture evidence marks this version old. Retrieval time alone did not determine staleness.</p>':''}</section>`:`<section class="section empty-state"><h2>No recorded candidate to offer</h2><p>Manual entry remains available when the formula can run honestly.</p></section>`;
  const fields=t.fields.map(([key,label])=>`<div class="form-field"><label for="f-${key}">${label}</label><input id="f-${key}" data-field="${key}" inputmode="decimal" value="${escapeHtml(state.draft[key]??'')}"><span class="helper">Normalized value used: ${normalized(state.draft[key])}</span></div>`).join('');
  const result=state.result?renderResult(state.result):'';return `<section><h1>${t.title}</h1><p class="lede">${t.question}</p><p class="limits">${t.scope}</p></section>${sourceHtml}<section class="section"><h2 class="section-heading">Your assumptions</h2>${fields}<div class="actions"><button class="primary" data-action="run" ${state.busy?'disabled':''}>${state.busy?'Calculating':'Run this scenario'}</button><button data-action="reset">Reset</button></div></section>${result}`}
function normalized(v){const n=strictNumber(v);return n===null?'Invalid or blank':String(n)}function escapeHtml(v){return String(v).replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}
function values(keys){return keys.map(k=>strictNumber(state.draft[k]))}
function reject(message){state.result={kind:'error',message};render();requestAnimationFrame(()=>{const e=document.querySelector('.field-error');if(e)e.focus()});log(`Rejected: ${message}`,true)}
function safeMoney(...nums){return finite(...nums)&&nums.every(n=>Math.abs(n)<=LIMIT)}
function calculate(){const id=state.tool;if(state.offline&&['S-02','EX-ESOP','EX-80C'].includes(id)){reject('This explorer needs a fresh authenticated calculation after you reconnect.');return}state.busy=true;render();setTimeout(()=>{state.busy=false;const result=compute(id);if(!result)return;state.result=result;render();requestAnimationFrame(()=>{const h=document.querySelector('#current-result');h?.focus();announce(`${TOOLS[id].title} result ready`)});emitProgress(id)},20)}
function compute(id){
  if(id==='S-05'){const [cash,fd,other,out]=values(['cash','fd','other','outgoings']);if(!finite(cash,fd,other,out)||[cash,fd,other].some(n=>n<0)||!(out>0)){reject('Enter finite non-negative accessible amounts and monthly outgoings greater than zero.');return}const total=cash+fd+other,months=total/out;if(!safeMoney(total)||!Number.isFinite(months)){reject('These inputs exceed the supported calculation domain.');return}return {kind:'single',value:`${months.toFixed(1)} months`,detail:`${money(total)} accessible divided by ${money(out)} monthly outgoings.`,formula:'accessible amounts / monthly outgoings'}}
  if(id==='S-03'){const [p,x,rate,years]=values(['currentSip','extraSip','rate','years']),n=Math.round(years*12);if(!finite(p,x,rate,years)||p<0||p>1e9||!(x>0&&x<=1e9)||rate<0||rate>100||n<1||n>720){reject('Use approved SIP, rate and 1-720 month limits. Additional SIP must be greater than zero.');return}const r=rate/1200,fv=m=>r===0?m*n:m*((Math.pow(1+r,n)-1)/r),base=fv(p),raised=fv(p+x),diff=raised-base;if(!safeMoney(base,raised,diff)){reject('The result exceeds ₹1 quadrillion.');return}return {kind:'compare',left:['Current path',money(base)],right:['Raised path',money(raised)],difference:`Arithmetic difference: ${money(diff)}`,detail:`Additional principal entered: ${money(x*n)}. ${n} end-month contributions.`,formula:'P × ((1+r)^n - 1) / r; zero rate uses P × n'}}
  if(id==='S-06'){const [p,rate,n]=values(['outstanding','loanRate','months']);if(!finite(p,rate,n)||!(p>0&&p<=1e12)||rate<0||rate>100||!Number.isInteger(n)||n<1||n>600){reject('Use a supported home/personal-loan balance, rate and 1-600 whole months.');return}const r=rate/1200;let emi;if(r===0)emi=p/n;else{const g=Math.pow(1+r,n);emi=p*r*g/(g-1)}const total=emi*n,interest=total-p;let bal=p,next=0;for(let m=0;m<Math.min(12,n);m++){const i=bal*r;next+=i;bal=bal+i-emi}if(!safeMoney(emi,total,interest,next)){reject('The result exceeds ₹1 quadrillion.');return}return {kind:'single',value:`${money(interest)} interest`,detail:`EMI ${money(emi)}. Total payable ${money(total)}. First ${Math.min(12,n)} months interest ${money(next)}.`,formula:'fixed monthly amortisation; zero rate uses principal / months'}}
  if(id==='S-07'){const [p,a,b,y]=values(['cashAmount','savingsRate','alternateRate','idleYears']);if(!finite(p,a,b,y)||!(p>0&&p<=1e12)||a<0||a>100||b<0||b>100||!(y>0&&y<=60)){reject('Use the approved amount, rates and 60-year boundary.');return}const left=p*Math.pow(1+a/100,y),right=p*Math.pow(1+b/100,y),diff=right-left;if(!safeMoney(left,right,diff)){reject('The result exceeds ₹1 quadrillion.');return}return {kind:'compare',left:[`First rate (${a}%)`,money(left)],right:[`Second rate (${b}%)`,money(right)],difference:`Second minus first: ${money(diff)}`,detail:'Input order is preserved. Positive, zero and negative differences are arithmetic only.',formula:'P × (1 + annual rate)^years'}}
  if(id==='S-01'){const [start,monthly,rate,target]=values(['corpus','monthly','corpusRate','target']);if(!finite(start,monthly,rate,target)||start<0||start>1e12||monthly<0||monthly>1e12||rate<0||rate>100||!(target>0&&target<=LIMIT)){reject('Use the approved corpus, contribution, rate and target limits.');return}if(start>=target)return {kind:'single',value:'0 months',detail:'The entered corpus is already at or above the user-set target.',formula:'current corpus ≥ target'};if(monthly===0&&rate===0)return {kind:'single',value:'Not reached',detail:'The balance does not move on these inputs within 720 months.',formula:'monthly simulation capped at 720'};let bal=start;for(let m=1;m<=720;m++){bal=bal*(1+rate/1200)+monthly;if(!safeMoney(bal)){reject('A monthly balance exceeded ₹1 quadrillion.');return}if(bal>=target)return {kind:'single',value:`${m} months`,detail:`${(m/12).toFixed(1)} years on these inputs.`,formula:'return first, then end-month contribution'}}return {kind:'single',value:'Not reached in 720 months',detail:'This is the explicit 60-year model boundary, not a forecast beyond it.',formula:'monthly simulation capped at 720'}}
  if(id==='S-02'){const x=strictNumber(state.draft.prepay),P=486200,E=10850,rate=9.4,r=rate/1200;if(!Number.isFinite(x)||!(x>0&&x<P&&x<=1e12)){reject('Prepayment must be greater than zero and below the recorded principal.');return}const tenure=-Math.log(1-r*P/E)/Math.log(1+r),P2=P-x,newTenure=-Math.log(1-r*P2/E)/Math.log(1+r),g=Math.pow(1+r,tenure),newEmi=P2*r*g/(g-1),savedTenure=(E*tenure-P)-((x+E*newTenure)-P),savedEmi=(E*tenure-P)-((x+newEmi*tenure)-P);if(!finite(tenure,newTenure,newEmi,savedTenure,savedEmi)||tenure>600||newTenure>600||!safeMoney(newEmi,savedTenure,savedEmi)){reject('Recorded loan values are outside the supported amortisation domain.');return}return {kind:'compare',left:['Same EMI',`${newTenure.toFixed(1)} months`],right:['Same tenure',`${precise(newEmi)} EMI`],difference:`Stored loan-rate hurdle: ${rate}%`,detail:`Interest arithmetic: ${precise(savedTenure)} and ${precise(savedEmi)}. Prepayment charges are assumed zero.`,formula:'stored fixed-amortisation loan; no investment return modeled'}}
  if(id==='EX-ESOP'){const units=240,strike=120,fmv=175,cost=units*strike,spread=units*(fmv-strike);return {kind:'single',value:precise(cost),detail:`${units} vested units. Recorded FMV paper spread ${precise(spread)}. FMV freshness unavailable.`,formula:'vested units × strike; spread = vested × (recorded FMV - strike)'}}
  if(id==='EX-80C'){if(String(state.draft.regime).trim().toLowerCase()!=='old')return {kind:'single',value:'No number',detail:'The fixture explorer calculates only the old-regime recorded-room mechanism.',formula:'fixture-only; production unavailable'};return {kind:'single',value:precise(56000),detail:'Known fixture contributions ₹94,000 against a fixture ₹1,50,000 cap. One unrecognised cadence is excluded.',formula:'min(₹1,50,000, max(₹0, ₹1,50,000 - known amount))'}}
  if(id==='EX-TERM'){const [annual,years,growth,cover]=values(['annualSupport','supportYears','growth','cover']);if(!finite(annual,years,growth,cover)||annual<0||!Number.isInteger(years)||years<1||years>100||growth<0||growth>100||cover<0){reject('Choose no annual change or enter supported finite components and 1-100 whole years.');return}let stream=0;for(let y=0;y<years;y++)stream+=annual*Math.pow(1+growth/100,y);const selected=[...state.included];const additions=(selected.includes('debt')?486200:0)+(selected.includes('goal')?1200000:0),modeled=Math.max(0,stream+additions),difference=cover-modeled;if(!safeMoney(stream,modeled,difference)){reject('The result exceeds the supported output domain.');return}return {kind:'compare',left:['Selected support model',money(modeled)],right:['Entered cover',money(cover)],difference:`Entered cover minus model: ${money(difference)}`,detail:`Only ${selected.length} recorded component${selected.length===1?'':'s'} selected. No adequacy verdict is supplied.`,formula:'support stream + selected additions - selected offsets'}}
}
function renderResult(r){if(r.kind==='error')return `<section class="section error-card" role="alert"><h2 class="field-error" tabindex="-1">Cannot run this scenario</h2><p>${r.message}</p></section>`;const body=r.kind==='compare'?`<div class="comparison"><div class="result-card"><strong>${r.left[0]}</strong><div class="result-value">${r.left[1]}</div></div><div class="result-card"><strong>${r.right[0]}</strong><div class="result-value">${r.right[1]}</div></div></div><p class="difference">${r.difference}</p>`:`<div class="result-card"><div class="result-value">${r.value}</div></div>`;return `<section class="section" id="current-result" tabindex="-1"><h2 class="section-heading">Result for these inputs</h2>${body}<p>${r.detail}</p><p class="formula">${r.formula}</p><p class="limits">Conditional arithmetic, not a forecast or recommendation. Nothing was saved.</p><div class="actions"><button data-action="edit">Edit inputs</button><button data-action="arya">Explore the mechanism with Arya</button><button data-action="reset">Reset</button></div></section>`}
function emitProgress(id){if(state.progressCap){log('Result remains usable. Participation cap simulated; no extra reward.');return}state.progressCount=Math.min(2,state.progressCount+1);log(`Current finite result. In-memory scenario_completed spy: ${id}, count ${state.progressCount}. No financial value recorded.`)}
function explorerEntry(id,opener){const t=TOOLS[id],c=CANDIDATES[state.account][id]||[];returnFocus=opener;if(id==='EX-TERM'){openDialog('Optional context',t.title,'<p>This fixture can offer debts and goals only after you agree. Declining keeps a blank manual path fully usable.</p>',[{label:'Start blank',action:`enter:${id}`},{label:'Agree and review sources',action:`consent:${id}`,primary:true}]);return}if(c.length===0){state.history.push({screen:'tools',tool:null,origin:null});state.screen='tool';state.tool=id;state.origin=t.origin;resetTool();state.sourceMode='empty';render();return}if(c.length===1){openDialog('Recorded source',t.title,`<p>${c[0][1]}: ${c[0][2]}. ${c[0][3]}. It is not selected yet.</p>`,[{label:'Cancel',action:'close'},{label:'Open explorer',action:`enter:${id}`,primary:true}]);return}openDialog('Choose a recorded source',t.title,c.map((x,i)=>`<button type="button" class="source-card" data-dialog-choice="${id}" data-index="${i}"><strong>${x[1]}</strong><span class="meta">${x[2]}. ${x[3]}</span></button>`).join(''),[{label:'Cancel',action:'close'}])}
function openDialog(label,title,body,actions=[]){$('dialog-label').textContent=label;$('dialog-title').textContent=title;$('dialog-body').innerHTML=body;$('dialog-actions').innerHTML=actions.map(a=>`<button type="button" data-dialog-action="${a.action}" class="${a.primary?'primary':''}">${a.label}</button>`).join('');$('action-dialog').showModal();requestAnimationFrame(()=>$('dialog-title').focus?.());bindDialog()}
function closeDialog(){$('action-dialog').close();returnFocus?.focus();returnFocus=null}
function bindDialog(){document.querySelectorAll('[data-dialog-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.dialogAction;if(a==='close')return closeDialog();if(a.startsWith('enter:')){const id=a.split(':')[1];closeDialog();enterTool(id,TOOLS[id].origin)}if(a.startsWith('consent:')){const id=a.split(':')[1];closeDialog();enterTool(id,TOOLS[id].origin);log('Optional context consent accepted in fixture memory only.')}});document.querySelectorAll('[data-dialog-choice]').forEach(b=>b.onclick=()=>{const id=b.dataset.dialogChoice;closeDialog();enterTool(id,TOOLS[id].origin)});$('action-dialog').onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();closeDialog()}}}
function bind(){
  document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>enterTool(b.dataset.tool));document.querySelectorAll('[data-explorer]').forEach(b=>b.onclick=()=>explorerEntry(b.dataset.explorer,b));document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>openDialog('Controlled destination',b.dataset.route,'<p>This confirms the route. No data or network action occurs.</p>',[{label:'Done',action:'close',primary:true}]));
  document.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=()=>{const k=b.dataset.candidate;state.included.has(k)?state.included.delete(k):state.included.add(k);state.result=null;render();log(`${k} ${state.included.has(k)?'included by user':'excluded by user'}.`)});
  document.querySelectorAll('[data-field]').forEach(i=>i.oninput=()=>{state.draft[i.dataset.field]=i.value;state.touched.add(i.dataset.field);if(state.result){state.result=null;render();log('Inputs changed. Prior result removed; run again for these values.')}});
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;if(a==='run')calculate();if(a==='reset'){resetTool();render();log('Draft, inclusions, result and errors cleared. Recorded candidates remain offered separately.')}if(a==='retry'){state.sourceMode='ready';render();log('Only the failed source was retried.')}if(a==='back')goBack();if(a==='tools'){state.screen='tools';state.tool=null;state.history=[];render()}if(a==='edit'){document.querySelector('[data-field]')?.focus()}if(a==='arya')openDialog('Exact payload confirmation','Explore with Arya',`<p>Send only the current scenario type, normalized inputs and formula boundary. No names, record IDs, institutions or source records.</p>`,[{label:'Cancel',action:'close'},{label:'Confirm fixture handoff',action:'close',primary:true}])});
}
function fixture(action){
  if(action==='reset'){Object.assign(state,{account:'Aarav',screen:'tools',tool:null,draft:{},included:new Set(),touched:new Set(),result:null,sourceMode:'ready',offline:false,permission:true,busy:false,progressCount:0,progressCap:false,history:[],origin:null,fixtureId:null});render();log('Fixture reset.');return}
  if(action==='loading'){state.sourceMode='loading';render();setTimeout(()=>{state.sourceMode='ready';render();log('Loading settled to ready without an empty flash.')},80);return}
  if(action==='partial'){state.sourceMode='partial';render();log('Partial source state. Available candidates retained.');return}
  if(action==='failure'){state.sourceMode='failure';render();log('Source-specific failure. Manual draft retained.',true);return}
  if(action==='stale'){state.sourceMode='stale';render();log('Known-stale state based on authoritative fixture version evidence.');return}
  if(action==='overflow'){if(state.screen==='tools')enterTool('S-07');state.draft.cashAmount='1000000000001';state.result=null;render();log('Boundary fixture loaded above D-171 amount limit.');return}
  if(action==='offline'){state.offline=!state.offline;render();log(state.offline?'Offline mode entered. No silent resend.':'Connection restored. Explicit retry still required.');return}
  if(action==='permission'){state.permission=false;state.draft={};state.included=new Set();state.result=null;state.history=[];closeDialogIfOpen();render();log('Permission lost. All financial state cleared.',true);return}
  if(action==='switch'){state.account=state.account==='Aarav'?'Meera':'Aarav';state.draft={};state.included=new Set();state.result=null;state.history=[];state.screen='tools';state.tool=null;state.sourceMode='loading';closeDialogIfOpen();render();setTimeout(()=>{state.sourceMode='ready';render();log('Destination account rendered. Late prior-account response discarded.')},80);return}
  if(action==='progress-cap'){state.progressCap=true;log('Progression cap/failure spy armed. Results will remain usable.');}
}
function closeDialogIfOpen(){if($('action-dialog').open)$('action-dialog').close()}
const STATE_FIXTURES=[
  'Suite loading','Suite ready','Deferred item','Scenario initial','Sources loading','Sources complete','Sources partial','Sources failed','No source records','Source stale',
  'Candidate edited','Candidate excluded','Critical unknown','Invalid input','Overflow/cap','Ready to run','Computing','Single result','Side-by-side result','Equal result',
  'Crossing/negative','Target reached','Target capped','Inputs changed','Reset','Refresh changes candidate','Retry succeeds','Network/5xx','Offline with draft','Offline without source',
  'Permission loss','Account transition','Late prior response','Explorer ineligible','Zero eligible loans','One eligible loan','Many eligible loans','Explorer consent','Explorer completion','Modal reopen',
  'Arya handoff','Progression success','Progression failure/cap','Loading accessibility','Error accessibility','Result accessibility','Keyboard/modal','Mobile/zoom','Theme/motion','Exit/return'
];
function loadAcceptanceState(number){
  fixture('reset');const id=`SC-${String(number).padStart(2,'0')}`,name=STATE_FIXTURES[number-1];state.fixtureId=id;
  const open=id=>{enterTool(id);state.sourceMode='ready'};
  if([1,5,44].includes(number))fixture('loading');
  else if(number===2)render();else if(number===3)openDialog('Deferred boundary','Unavailable tool','<p>This item is outside the approved prototype and returns to Tools without a product prompt.</p>',[{label:'Return to Tools',action:'close',primary:true}]);
  else if([4,6,16].includes(number))open('S-05');else if(number===7){open('S-05');fixture('partial')}else if([8,28].includes(number)){open('S-05');fixture('failure')}
  else if(number===9){state.account='Kabir';open('S-05')}else if(number===10){open('S-05');fixture('stale')}
  else if(number===11){open('S-05');state.draft.cash='75000';state.touched.add('cash');render()}else if(number===12){open('S-05');state.included.add('fd');render();document.querySelector('[data-candidate="fd"]')?.click()}
  else if(number===13){open('S-05');state.draft.outgoings='';render()}else if(number===14){open('S-05');state.draft.outgoings='0';calculate()}else if(number===15)fixture('overflow')
  else if(number===17){open('S-05');calculate()}else if(number===18){open('S-05');state.result=compute('S-05');render()}else if(number===19){open('S-03');state.result=compute('S-03');render()}
  else if(number===20){open('S-07');state.draft.alternateRate=state.draft.savingsRate;state.result=compute('S-07');render()}else if(number===21){open('S-07');state.draft.savingsRate='10';state.draft.alternateRate='4';state.result=compute('S-07');render()}
  else if(number===22){open('S-01');state.draft.target='300000';state.result=compute('S-01');render()}else if(number===23){open('S-01');state.draft.monthly='0';state.draft.corpusRate='0';state.result=compute('S-01');render()}
  else if(number===24){open('S-05');state.result=compute('S-05');state.draft.cash='70000';state.result=null;render()}else if(number===25){open('S-05');resetTool();render()}
  else if(number===26){open('S-05');state.draft.fd='95000';state.touched.add('fd');setBanner('Recorded value changed. Keep your manual value, accept the new value, or reset.')}
  else if(number===27){open('S-05');state.sourceMode='failure';render()}else if(number===29){open('S-05');fixture('offline')}else if(number===30){state.account='Kabir';open('S-05');fixture('offline')}
  else if(number===31)fixture('permission');else if([32,33].includes(number))fixture('switch');else if([34,35].includes(number)){state.account='Kabir';explorerEntry('S-02',document.querySelector('[data-explorer="S-02"]'))}
  else if(number===36)explorerEntry('S-02',document.querySelector('[data-explorer="S-02"]'));else if(number===37){state.account='Mira';explorerEntry('S-02',document.querySelector('[data-explorer="S-02"]'))}
  else if(number===38)explorerEntry('EX-TERM',document.querySelector('[data-explorer="EX-TERM"]'));else if(number===39){enterTool('EX-ESOP','Workplace grant');state.result=compute('EX-ESOP');render()}
  else if(number===40)explorerEntry('S-02',document.querySelector('[data-explorer="S-02"]'));else if(number===41){open('S-05');state.result=compute('S-05');render();document.querySelector('[data-action="arya"]')?.click()}
  else if(number===42){open('S-05');state.result=compute('S-05');render();emitProgress('S-05')}else if(number===43){open('S-05');state.result=compute('S-05');render();fixture('progress-cap')}
  else if(number===45){open('S-05');state.draft.outgoings='0';calculate()}else if(number===46){open('S-05');state.result=compute('S-05');render();document.querySelector('#current-result')?.focus()}
  else if(number===47)explorerEntry('S-02',document.querySelector('[data-explorer="S-02"]'));else if([48,49].includes(number))open('S-05');else if(number===50){open('S-05');state.origin='Portfolio'}
  log(`${id} ${name} fixture loaded.`);
}
$('state-fixture').innerHTML='<option value="">Choose a canonical state</option>'+STATE_FIXTURES.map((name,index)=>`<option value="${index+1}">SC-${String(index+1).padStart(2,'0')} ${name}</option>`).join('');
$('state-fixture').onchange=e=>{if(e.target.value)loadAcceptanceState(Number(e.target.value))};
$('validation-task').onchange=e=>{state.task=e.target.value;renderTask()};function renderTask(){const t=TASKS[state.task];$('task-name').textContent=t.name;$('task-prompt').textContent=t.prompt;$('task-fixture').textContent=t.fixture}
$('back').onclick=goBack;$('close').onclick=()=>{const destination=state.origin||'Tools';state.screen='tools';state.tool=null;state.origin=null;state.history=[];resetTransientResult();render();log(`Closed. Returned to ${destination}. Nothing saved.`)};document.querySelectorAll('[data-fixture]').forEach(b=>b.onclick=()=>fixture(b.dataset.fixture));
renderTask();render();
